    "stemTitle": "生徒Ａと生徒Ｂの会話文",
    "stem": "Ａ：海外からの観光客が多いね。世界遺産、文化財や史跡、伝統工芸、和食やポップカルチャーまで、多くの人々にとって魅力的なんだろう。日本文化はスゴイな。誇らしいし、優れた文化として次世代に伝えていきたいよ。\nＢ：自分たちの文化が優れていると考える心情はわからなくはないけれど、その結果　ア　に陥らないよう注意したいね。そもそも文化の価値は比べられるのかな。\nＡ：例えば、ある国や地域の特定の文化財が世界遺産に登録されたとなると、登録されていない場合よりも価値があるということだと思うよ。\nＢ：なるほど。他方で、世界遺産登録の前と後で、その文化財の価値が急に変わるのかな。また、世界遺産がない国や少ない国にも特徴的な文化は様々あるよね。私たちが何らかの文化遺産制度による認定や登録をとりわけ重視する姿勢をとるとき、それは　イ　ことになるのではないかな。\nＡ：考えたことがなかった視点だな。多様な文化を理解する際には、自分の捉え方に思い込みがないか、気をつけてみるよ。\n\nアに入る語句\nａ　多文化主義\nｂ　エスノセントリズム\nｃ　文化相対主義\n\nイに入る記述\nｄ　特定の基準による評価を受け入れずに文化に独自の価値づけをしている\nｅ　特定の基準がもつ権威に依拠して文化を評価し序列づけている",
