    "stem": "Ⅰ　哲学カフェの参加者にも、話し合うときの態度はいろいろあるけど、お互い安心して話せるように、穏やかな態度で相手の発言を最後まで聞き、よく考えてから発言するように取り決めたところ、対話が活発にできるようになった。これらの事実が何度もあったことから、活発な哲学対話は、安心して話せる取り決めがあれば可能になるという経験則が導き出せるね。\nⅡ　人間には、自分の考えや意見を自由に述べる権利があり、お互いに認め合い尊重し合う義務がある。そうであるならば、哲学カフェに限らず、職場でも学校でも、参加者がお互いに、相手には自由に発言する権利があると考え、相手の話を尊重して最後までしっかりと聞くことを、対話のルールにしなければならないことになるね。\nⅢ　哲学カフェに初めて参加した人が素朴な質問をしてくれると、これまで繰り返し問うてきた問題に新たな光が当てられて、問いが深まった。そんなときに、対話のおもしろさが感じられた。同じ実感を他の参加者たちももっていた。これらの経験を基にして、どんなに素朴であっても、率直に質問や疑問を出し、問いを深めていくことが哲学対話の方針になったんだよ。",
