    "explanation": "資料に書いてあることだけを根拠に判断する、典型的な読み取り問題である。選択肢が「過去」と「今日」のどちらの話かを見分けることが鍵になる。\n資料の要点は二つ。第一に、過去は氏族など多様な団体が物理的暴力を普通の手段として用いていた。第二に、今日の国家は一定の領域内で「正当な物理的暴力行使の独占」を要求し、暴力行使の権利の唯一の源泉とみなされている。3はこの第二の点をそのまま述べているので正しい。\nこの考え方は、社会学者マックス・ウェーバーが示した近代国家の定義として有名である。警察や軍隊のように、実力を用いてよい主体を国家だけに限り、私的な暴力（自力救済）を原則として禁じるという発想が、近代国家と法の支配の前提になっている。",
