    "explanation": "憲法第20条の条文をどれだけ正確に覚えているかが問われる。\nア：正しい。信教の自由は、①内心における信仰の自由、②宗教的行為の自由、③宗教的結社の自由の三つを含むと理解されている。宗教団体を作る自由は③にあたる。\nイ：誤り。憲法第20条1項後段は「いかなる宗教団体も、国から特権を受け、又は政治上の権力を行使してはならない」と定めている。「一定の要件を満たせば認められる」という例外はない。\nウ：正しい。憲法第20条3項は「国及びその機関は、宗教教育その他いかなる宗教的活動もしてはならない」と定める。条文どおりの記述である。なお、ここで禁じられるのは特定の宗教のための教育や活動であり、宗教一般について学ぶ知識教育まで禁じられるわけではない。\nよってアとウ。政教分離をめぐる裁判では、目的が宗教的意義をもち効果が宗教への援助・助長・圧迫になるかで判断する「目的効果基準」が使われてきた（津地鎮祭訴訟、愛媛玉ぐし料訴訟など）。",
