    "question": "主権国家より上位に立つものがないので、国際社会は社会というよりは自然状態であるといわれることがあると知り、関連する文献を調べた。次の記述ア～ウは、それぞれ『統治二論（市民政府二論）』、『戦争と平和の法』、『リヴァイアサン（リバイアサン）』の一節のうちのいずれかである（なお、表記を改めた箇所や省略した箇所がある）。記述ア～ウと後の著者名a～cとの組合せとして正しいものを、後のうちから一つ選べ。\n\nア　「自然状態はそれを支配する自然法をもち、すべての人間がそれに拘束される。…（略）…その自然法たる理性は、…（略）…何人も他人の生命、健康、自由、あるいは所有物を侵害すべきではないということを教えるのである。」\nイ　「人びとが、かれらすべてを威圧しておく共通の権力なしに、生活しているときには、…（略）…自身のつよさと自分自身の工夫とが与えるもののほかには、なんの保証もなしに生きている…（略）…。」\nウ　「戦の最中には、法は沈黙するかもしれないが、…（略）…自然が定め、または万民の合意が定立したところのものは依然効力を有する…（略）…人民の間には、戦争を行うについて、かつまた戦争に関して有効なる共通法が存在する…（略）…。」\n\na　グロティウス（グロチウス）　　b　ホッブズ　　c　ロック",
