    "question": "日本の内閣の運営のあり方の特徴をまとめた次の文章中の空欄　ア　～　ウ　に当てはまる語句の組合せとして最も適当なものを、後のうちから一つ選べ。\n\n　内閣の運営に関する特徴の一つは合議制の原則である。これは、内閣の意思決定は、内閣総理大臣（首相）と国務大臣の合議、すなわち閣議によらなければならないとするものである。閣議における決定は、　ア　によることが慣行となっている。\n　また、首相指導の原則がある。これは、国務大臣の任免権をもつ首相が、　イ　として政治的リーダーシップを発揮するというものである。\n　このほか、分担管理の原則がある。これは、各省の所掌事務はその主任の国務大臣が分担して管理するというものである。なお、日本国憲法の規定によると、法律及び政令には、すべて主任の国務大臣が署名し、　ウ　が連署することになっている。",
