    "points": 3,
    "noShuffle": true,
    "question": "他国への日本の選挙監視団の派遣について、生徒Xと生徒Yが次のようなやり取りを行った。Xが二重下線部で示したように考えることができる理由として最も適当なものを、後のうちから一つ選べ。\n\nX：途上国で行われる選挙に、選挙監視団が派遣されたって聞いたことがあるよ。たとえば、カンボジアやネパールで新憲法を制定するための議員を選ぶ選挙が行われた際に、選挙監視要員が派遣されたんだ。\nY：なぜこうした国は、憲法の制定に関わるような問題に、外国からの選挙監視団を受け入れたんだろう？　そして、どうしてそれが国際貢献になるのかな？\nX：選挙監視団の目的は、自由で公正な選挙が行われるようにすることだよね。＜二重下線部＞民主主義における選挙の意義という観点から考えれば、そうした選挙を実現させることは、その国に民主的な政治体制が定着するきっかけになるよね。＜／二重下線部＞民主的な政治体制がうまく機能するようになれば、再び内戦に陥って国民が苦しむようなことになるのを避けられるんじゃないかな。\nY：そうだね。それに、自由で民主的な政治体制が確保されている国の間では戦争は起きないって聞いたこともあるよ。もしそうだとすると、選挙監視団を派遣することは国際平和にもつながっているとも言えるね。",
    "choices": [
      "民主主義においては、国民に選挙を通じた政治参加を保障することで、国の統治に国民全体の意思を反映すべきものとされているから。",
      "民主主義においては、大衆が国の統治を特定の個人や集団による独裁に委ねる可能性が排除されているから。",
      "民主主義においては、暴力によってではなく裁判によって紛争を解決することとなっているから。",
      "民主主義においては、国民が政治的意思を表明する機会を選挙以外にも保障すべきものとされているから。"
    ],
    "answer": 0,
    "explanation": "何を問われているのかを正確につかむことが大切である。問われているのは「自由で公正な選挙を実現させることが、なぜ民主的な政治体制の定着につながるのか」を、＜民主主義における選挙の意義＞という観点から説明する理由である。したがって、選挙そのものの働きを述べた選択肢を選ぶ。\n1が正解。民主主義とは、国の政治のあり方を最終的に国民が決めるという考え方であり、その中心にある仕組みが選挙である。国民に選挙を通じた政治参加を保障し、国民全体の意思を統治に反映させることが選挙の意義であって、自由で公正な選挙が根づけば民主的な政治体制も定着していく、という筋道が成り立つ。\n2から4は、それぞれ内容として誤っていたり（2）、選挙の意義とは別の話であったり（3・4）するため、二重下線部の理由にならない。とくに4は、選挙「以外」の参加手段の話になっているため、選挙を実現させることの意義の説明としてはずれている。",
