    "explanation": "【ア】地方分権一括法（1999年成立、2000年施行）は、国と地方の関係をそれまでの「上下・主従」から「対等・協力」の関係へ改めることをめざした。\n【イ】機関委任事務が廃止され、地方の事務は自治事務と法定受託事務に再編された。都市計画の決定は地方公共団体が自らの判断で処理する自治事務である。法定受託事務は本来国が果たすべき役割にかかわる事務を法律で地方に委託するもので、国政選挙、旅券の交付、戸籍事務などが該当する。\n【ウ】国の関与に不服がある場合、地方公共団体は総務省に置かれる国地方係争処理委員会に審査の申出ができ、同委員会は審査のうえ国の機関に勧告できる。審査結果に不服があるときは高等裁判所に訴訟を提起できる。\nよってア＝対等・協力、イ＝自治事務、ウ＝国地方係争処理委員会となる。",
