    "question": "次の文章中の空欄　ア　・　イ　に当てはまる語句の組合せとして正しいものを、次のうちから一つ選べ。\n\n　少子高齢化が進むにつれ、人口減少に直面する地方都市のあり方が問われるようになった。これに対応して、商業や医療など生活に必要な機能を担う施設を都市の中心部に集中させ、中心市街地を活性化させると同時に行政サービスの効率化を図る　ア　の考え方もある。\n　また、居住地ではなくても、応援したい地方公共団体に寄付をすると、その額に応じて所得税と住民税が控除される　イ　という仕組みがある。これは地方公共団体の間で税収を移転させる効果があり、地域活性化や被災地の復興支援のために、これを利用する人もいる。",
