    "question": "景気循環に関する次の資料1と、図の資料2～4を読み直している。資料2～4は、1989年から1994年までの日本の、GDP、民間設備投資、民間部門の在庫、それぞれの実質額が前年に比べてどのように増減したかを示している。なお、資料2～4中の空欄　ア　～　ウ　には、「GDP」、「民間設備投資」、「民間部門の在庫」のいずれかの語句が当てはまる。空欄　ア　～　ウ　に当てはまる語句の組合せとして最も適当なものを、後のうちから一つ選べ。\n\n【資料1　景気循環に関する説明】\n○景気循環は、以下のような経過にしたがうといわれる。\n・生産の増加に対して需要の増加が十分でないとき、商品の売れ残りが増加し企業の利潤は減少する。\n・企業の利潤の減少にともない、雇用は減少し、景気は後退する。\n・景気の後退は、企業による生産の抑制や設備投資の減少とさらなる雇用の減少を促し、経済は不況に至る。\n・企業による過剰在庫の処分や過剰設備の整理とともに需要が増加し、景気は回復し、さらに好況に向かう。この中で企業の設備投資も活発化し、生産や雇用も増加していく。\n○1989年から1994年までの日本にも、上記のような経過が観察される。",
