    "explanation": "二つのことを同時に考える必要がある。\n第一に、代替品である安い冷凍野菜が買えるようになるので、同じ価格でも生鮮野菜を買う量は減る。つまり需要曲線は全体として左へ移動する。この時点で、右や上へ移動する③・④は消える。\n第二に、問題文の「生鮮野菜の価格が高いほど、生鮮野菜より冷凍野菜を好んで購入する傾向にある」という条件を使う。価格が高い領域ほど冷凍野菜へ乗り換える人が多い、つまり価格の高い側ほど需要の減り方が大きいということである。上の方が大きく左へ寄り、下の方はあまり動かないので、曲線は横に寝た形（傾きがゆるやか）になる。価格の変化に対して需要量が大きく反応する状態であり、需要の価格弾力性が大きくなったともいえる。\nこの二つを満たすのは②である。代替財が現れると、その財の需要は減るだけでなく、価格に対して敏感になる、という点をおさえておきたい。",
