    "verifiedAt": "2026-09-01",
    "image": "images/civics/r3-3-4-bs.webp",
    "imageAlt": "銀行のバランスシートの変化を示した3つの模式図。左の「経済不況以前」は、資産が貸出債権とその他、負債・純資産が預金と資本金。中央の「経済不況」は、貸出債権の一部が不良債権となって区分され、資産・負債の大きさは変わらない。右の「不良債権処理」は、不良債権が資産から取り除かれて総資産が小さくなり、預金の大きさは変わらないまま資本金が大きく減少している。"
