    "noShuffle": true,
    "question": "1980年代から、自由な金融市場の発展を促すため、先進国での金融規制の緩和は珍しくなくなった。そうした動きに関連した日本の銀行制度に関する次の記述アとイの正誤の組合せとして正しいものを、後のうちから一つ選べ。\n\nア　日本銀行は、バブル経済崩壊後、国債を市場で売買することにより市場金利への影響力を行使したことはない。\nイ　日本版金融ビッグバン以前は、経営基盤の弱い銀行も規制や保護により利益を確保できたため、流通業など他業種から銀行業への参入が増えていた。",
