    "imageAlt": "日本と発展途上国・新興国の関係を示すフロー図。日本側は「激化する国際競争や人件費高騰による日本企業の負担感の増大」、発展途上国・新興国側は「経済特区開設などの外資導入を推進」から始まり、両者が「日本企業の発展途上国・新興国への進出」に合流する。そこから「製造業を中心とした企業の海外移転に伴う産業の空洞化」と空欄アに分かれ、さらに「日本企業による部品供給と進出先での組立て」を経て、「経済成長の停滞や経済格差の拡大」、空欄イ、「中間層の拡大などによる自動車や家電の普及率の上昇」の3つに分かれる。"
