    "explanation": "指標ごとに「どれくらい変化しうるか」「増えるはずか減るはずか」を考えれば、計算をしなくても対応づけられる。\nまず基準となる名目GNIは、2002年の100に対して2015年は約400へ、13年間で約4倍になっている。経済が大きく成長した5か国であることがわかる。\nア（約220）：2倍以上に増えている。経済成長にともなって急速に伸びる項目なので電力発電量である。工業化と生活の電化が進めば発電量は数倍になりうる。\nイ（約60）：4割ほど減っている。増えるのではなく減るのが望ましい項目、すなわち栄養不良の人口割合である。経済発展によって食料事情が改善したことを示す。\nウ（約105）：ほぼ横ばいでわずかに増えている。平均寿命は、たとえば65歳から68歳へ延びても指数では105程度にしかならない。年数で測る指標は変化率が小さくなるという点がポイントである。\nよってア＝電力発電量、イ＝栄養不良の人口割合、ウ＝平均寿命。",
