    "question": "地球環境問題の取組みに関する歴史的展開を踏まえて、京都議定書（1997年採択）、パリ協定（2015年採択）の位置づけや内容について調べた。この二つの条約に関する記述として最も適当なものを、次のうちから一つ選べ。",
