    "explanation": "京都議定書は、先進国（附属書I国）にのみ数値目標付きの温室効果ガス削減義務を課した。これに対しパリ協定は、先進国・発展途上国を問わずすべての締約国に、自国が決定する貢献（NDC）を作成・提出し、それに向けた国内対策をとることを義務づけている（削減目標の水準そのものは各国が決めるが、取り組むこと自体は義務である）。同時に、先進国には発展途上国への資金支援の義務が定められており、「共通だが差異ある責任」の考え方が引き継がれている。したがって選択肢4が最も適当。\nなお「共通だが差異ある責任」とは、地球環境問題に取り組む責任は各国に共通するが、その程度は歴史的な排出量や経済力に応じて異なるという考え方であり、先進国のみに責任があるという意味ではない。",
