    "stem": "Ｘ：私はこれまで意識してこなかったけれど、不慮の事故や病気はだれにでも起こりうるし、年をとるにつれてさまざまなリスクは高まっていくよね。現役世代を含めたすべての世代のだれもが安心して暮らせる社会の実現のためには、何が必要になってくるのかな。\nＹ：まずは、高齢者や障害者も社会の中でほかの人々と同じような暮らしを送り、ともに生活するという　ア　という考え方が重要だよね。\nＺ：その点、高齢者や障害者にとって生活の支障となるものを取り除こうというバリアフリーの取組みは、日本でも法律的な裏づけも得て一般化してきているよ。\nＸ：バリアフリー化が進めば、雇用の障壁となっている問題も改善しそうだね。\nＹ：現在、国、地方公共団体や企業などに対して、　イ　が法律で義務づけられているのは、雇用における問題の改善が早急に求められるということを示しているとも考えられるね。\nＺ：だとすれば、法律は国会で制定され、改正されるものだから、18歳以上の高校生ももっている選挙権は、社会の変化を促すことにつながっているといえるね。\n\nアに当てはまる語句\nａ　ワーク・ライフ・バランス\nｂ　ノーマライゼーション\n\nイに当てはまる記述\nｃ　定年制を廃止すること\nｄ　障害者を職員や従業員の一定比率以上雇用すること",
