    "stem": "日本の水道事業は、法律上、市町村による経営が原則とされている。\n水道事業の特性として、以下のことがあげられる。第一に、日常生活に欠くことができないため公共性が高いことである。第二に、浄水場などの大規模な設備を必要とするので、生産を増加することで生産量1単位当たりの費用が　ア　するという規模の経済が当てはまることである。第三に、税金ではなく、サービスの提供を受ける者から徴収する料金での運営を基本とすることである。\n水道事業には、人口減少に伴う料金収入の減少、老朽化した施設等の更新や改修、耐震化のための投資の増大などの問題がある。その解決策の一つとして、最適な事業経営単位という観点から、複数の市町村が一体的に事業に取り組む広域化が推進されている。広域化の効果として、　イ　ことを通じて規模の経済が働き、長期的に安定した事業の継続につながる。しかし、中山間地域ではこうした効果が十分に見込めない可能性がある。水道事業の経営は、地域の実情を考慮して進める必要がある。\n\nアに入る語句\nａ　上昇\nｂ　低下\n\nイに入る記述\nｃ　施設の共同設置や共同利用により、維持管理費用が削減される\nｄ　採算の合わない事業者の赤字を、他の事業者の収益で補填する",
