    "explanation": "ア：規模の経済（スケールメリット）とは、生産規模を大きくするほど生産物1単位当たりの費用が下がることをいう。大規模な設備が必要な事業では、設備費という固定費が多くの生産量に分散されるため単位当たり費用が低下する。したがってｂ「低下」。イ：広域化によって規模の経済が働く仕組みなので、施設を共同で設置・利用して維持管理費用を減らすというｃが入る。ｄは赤字を他の事業者の収益で埋める内部補助の話で、費用が下がるわけではないから規模の経済の説明にならない。よって「ア―ｂ　イ―ｃ」。",
