    "explanation": "ア：公共サービスから受ける利益（便益）に応じて負担するのが応益負担。観光客が増大させる公共サービスの費用を宿泊客が負担するという説明は応益負担の考え方であり、1泊いくらの定額課税がこれになじむ。イ：負担能力（経済力）に応じて負担するのが応能負担。宿泊料金の一定割合という定率課税は、料金の高さを経済力の代わりとみて負担を変える仕組みなので応能負担にあたる。ウ：需要の価格弾力性とは、価格の変化に対して需要量がどれだけ変化するかの度合い。税が上乗せされて価格が少し上がっただけで宿泊客数が「大幅に」落ち込むと考えるのは、弾力性が大きいと想定していることになる。よって「応益・応能・大きい」。",
