    "stem": "一国の経済活動の規模を測る指標には様々なものがあるが、代表的なものの一つとして、実質GDP（国内総生産）がある。経済成長とは、実質GDPの値が大きくなり、一年間に国内で生み出された　ア　の合計が増加することをいう。それによって、企業の利潤や個人の給与なども増え、政府においては、税収の増加が見込まれる。\n一国の経済成長率を高めるためには、企業による　イ　が重要である。こうして効率性が高まったり、生産性が上昇したりする。労働力・資源・資金などがより適切に社会に分配されることが期待される。\n現実には、経済成長が推し進められるなかで、国民の間に経済的な格差が生じてしまう点も見過ごせない。このような状況に対して、累進課税制度が設けられており、その代表的な税として　ウ　がある。政府は、様々な税制を整備し、公平性を図ろうとしている。",
