    "explanation": "国民経済計算の指標は次のようにつながっている。\n・総生産額 −中間生産物 ＝ GNP（国民総生産）\n・GNP −固定資本減耗 ＝ NNP（国民純生産）\n・NNP −（間接税−補助金）＝ NI（国民所得）\n・GNP −海外からの純所得 ＝ GDP（国内総生産）\nアは、GNPからNNPを求める段階なので固定資本減耗（生産設備の減価償却分）。イは、「国民」を基準とするGNPから「国内」を基準とするGDPを求める段階なので、海外からの純所得（海外で日本国民が得た所得−国内で外国人が得た所得）である。よって1が正しい。\n中間生産物は総生産額からGNPを求める段階で差し引くものであり、経常海外余剰は輸出等から輸入等を差し引いた額で、GNPとGDPの差ではない。",
